theorem usa2018_p1 (a b c : ℝ) :
    a > 0 → b > 0 → c > 0 → a + b + c = 4 * (a * b * c) ^ ((1 : ℝ) / 3) →
    2 * (a * b + b * c + c * a) +
     4 * (min (min (a * a) (b * b)) (c * c)) ≥ a^2 + b^2 + c^2  := by
  intro ha hb hc heq
  wlog h1 : a ≤ b with H1
  wlog h2 : a ≤ c with H2
  wlog h3 : b ≤ c with H3
  exact ⟨
    by
      move_add [←(b^2)];
      convert (H1 b a c hb ha hc (by ring_nf) (by rw [min_comm (a*a) (b^2)])) using 3;
      linear_combination (norm := (ring_nf)) 1 * heq;
      linarith [le_of_lt (not_le.mp h1)];
    by
      move_add [(c^2)]; wlog h3 : b ≤ c with H3;
      move_add [(a^2)]; convert (H3 a c b ha hc hb (by rw [min_comm, ←min_assoc, min_comm (a*a)])) using 3;
      linear_combination (norm := (ring_nf)) 1 * heq;
      linarith [le_of_lt h3, le_of_lt (not_le.mp h2)];
    by
      move_add [(b^2)];
      convert (H3 a c b ha hc hb (by rw [min_comm, ←min_assoc, min_comm (a*a)])) using 3;
      linear_combination (norm := (field_simp; ring_nf)) 1 * heq;
      linarith [le_of_lt (not_le.mp h1), le_of_lt h2, le_of_lt h3]

problem usa2018_p1 (a b c : ℝ) :
    a > 0 → b > 0 → c > 0 → a + b + c = 4 * (a * b * c) ^ ((1 : ℝ) / 3) →
    2 * (a * b + b * c + c * a) +
     4 * (min (min (a * a) (b * b)) (c * c)) ≥ a^2 + b^2 + c^2  := by
  intro ha hb hc heq
  wlog h1 : a ≤ b;
  wlog h2 : a ≤ c;
  wlog h3 : b ≤ c;
  move_add [←(c^2)]; use h1, h2, h3; linarith [heq] (by ring_nf)
